-- Robotics/Embedded/IoT pathway ("Vector Division") Act 24 -- "Path
-- Planning" content, closing Arc IV ("Teach Machines Where They Are,"
-- Acts 18-24). World row world-vec-path-planning already exists (created
-- by 20260813240000). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every other
-- pathway. No new ChallengeType needed -- reuses story_dialogue,
-- multiple_choice, drag_and_drop, investigation, interactive_diagram,
-- browser_simulation and boss_encounter. A full evacuation drill puts
-- the complete perceive-localize-map-plan stack (Acts 21-23) to its
-- first real combined test: graphs, grid search, a BFS/DFS recap,
-- Dijkstra, A*, heuristics, cost maps, global planning, local planning,
-- obstacle avoidance and dynamic obstacles, synthesized in the "Evacuate
-- the Sector" boss. Closes on the pivot into Act 25, "ROS 2" --
-- everything built so far exists as one-off code bolted onto one robot,
-- and scaling to a fleet needs a real shared framework.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-path-planning', 'world-vec-path-planning', 'path-planning', '4G - Path Planning', 'Turn a perceived, localized and mapped sector into a route a robot can actually follow -- graphs, grid search, BFS and DFS, Dijkstra''s algorithm, A*, heuristics, cost maps, global and local planning, obstacle avoidance and dynamic obstacles -- while Vector Division puts the complete stack through a live sector evacuation drill.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-path-planning-1', 'campaign-vec-path-planning', 'graphs-and-search', 'Graphs and Search', 'Graphs in robotics, grid search, a BFS/DFS recap, Dijkstra''s algorithm, A* and heuristics.', 1),
  ('operation-vec-path-planning-2', 'campaign-vec-path-planning', 'planning-under-pressure', 'Planning Under Pressure', 'Cost maps, global planning, local planning, obstacle avoidance, dynamic obstacles, and the full evacuation drill.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-path-planning-01', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-1', 'graphs-in-robotics', 'Graphs in Robotics', 'A full evacuation drill puts the complete stack to its first real test: perceive, localize, map and now plan a safe path through a sector, live, with moving obstacles in the way. Dr. Lin Ortega starts where every planner has to start -- turning the sector into a graph a search algorithm can actually reason about.', 'beginner', ARRAY['imani','lin','byte'], null, null, '{"type":"simulation","simulationId":"graphs-in-robotics-sim"}'::jsonb, '{"xp":310,"credits":25}'::jsonb, false, 1),
  ('mission-vec-path-planning-02', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-1', 'grid-search', 'Grid Search', 'A hand-drawn graph does not scale to a forty-thousand-cell sector. A grid overlaid on the current map builds one automatically -- and raises the first real design choice: how a cell is allowed to connect to its neighbors.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-path-planning-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"grid-search-sim"}'::jsonb, '{"xp":310,"credits":30}'::jsonb, false, 2),
  ('mission-vec-path-planning-03', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-1', 'bfs-dfs-recap', 'BFS and DFS Recap', 'Before weight enters the picture, the plain graph searches get one last look -- what breadth-first and depth-first search actually guarantee, and exactly what that guarantee leaves out.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-path-planning-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"bfs-dfs-recap-sim"}'::jsonb, '{"xp":320,"credits":30}'::jsonb, false, 3),
  ('mission-vec-path-planning-04', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-1', 'dijkstras-algorithm', 'Dijkstra''s Algorithm', 'Every edge in the sector graph now carries a real cost. Dijkstra''s algorithm turns that cost into a guarantee: the lowest-cost route, provably, as long as nothing costs less than zero.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-path-planning-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"dijkstras-algorithm-sim"}'::jsonb, '{"xp":320,"credits":35}'::jsonb, false, 4),
  ('mission-vec-path-planning-05', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-1', 'a-star-search', 'A* Search', 'Dijkstra is correct and wasteful -- it searches evenly in every direction with no sense of where the goal actually is. A* adds exactly one idea to fix that, without giving up the guarantee.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-path-planning-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"a-star-search-sim"}'::jsonb, '{"xp":330,"credits":35}'::jsonb, false, 5),
  ('mission-vec-path-planning-06', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-1', 'heuristics', 'Heuristics', 'A* is only as good as the number it trusts. Choosing that number correctly, and rejecting the ones that look faster but lie, is its own real skill.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-path-planning-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"heuristics-sim"}'::jsonb, '{"xp":330,"credits":35}'::jsonb, false, 6),
  ('mission-vec-path-planning-07', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-2', 'cost-maps', 'Cost Maps', 'A weight has to come from somewhere. Sera Holt makes sure it comes from more than distance alone -- from a cost map that treats proximity to danger as a cost in its own right, long before the robot is ever close enough for it to matter.', 'beginner', ARRAY['lin','sera'], '{"requiredMissionIds":["mission-vec-path-planning-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"cost-maps-sim"}'::jsonb, '{"xp":340,"credits":40}'::jsonb, false, 7),
  ('mission-vec-path-planning-08', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-2', 'global-planning', 'Global Planning', 'Cost map plus A*, run once across the whole sector before the robot moves -- a global plan is only as trustworthy as the map it is computed on.', 'beginner', ARRAY['lin','imani'], '{"requiredMissionIds":["mission-vec-path-planning-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"global-planning-sim"}'::jsonb, '{"xp":340,"credits":40}'::jsonb, false, 8),
  ('mission-vec-path-planning-09', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-2', 'local-planning', 'Local Planning', 'A global route is a shape, not a set of instructions for this instant. Local planning is what actually decides, moment to moment, how the robot moves inside it.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-path-planning-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"local-planning-sim"}'::jsonb, '{"xp":350,"credits":40}'::jsonb, false, 9),
  ('mission-vec-path-planning-10', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-2', 'obstacle-avoidance', 'Obstacle Avoidance', 'The first real test of local planning is something the global map never saw coming. Sera''s standard is not just missing it -- it is missing it with real margin.', 'beginner', ARRAY['lin','sera'], '{"requiredMissionIds":["mission-vec-path-planning-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"obstacle-avoidance-sim"}'::jsonb, '{"xp":350,"credits":45}'::jsonb, false, 10),
  ('mission-vec-path-planning-11', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-2', 'dynamic-obstacles', 'Dynamic Obstacles', 'A held-still obstacle and a moving one are not the same problem. An evacuation drill guarantees the sector is full of the second kind.', 'beginner', ARRAY['lin','imani'], '{"requiredMissionIds":["mission-vec-path-planning-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"dynamic-obstacles-sim"}'::jsonb, '{"xp":360,"credits":45}'::jsonb, false, 11),
  ('mission-vec-path-planning-12', 'world-vec-path-planning', 'campaign-vec-path-planning', 'operation-vec-path-planning-2', 'evacuate-the-sector', 'Evacuate the Sector', 'Every piece this Act taught, turned on one live evacuation drill, closes the whole of Arc IV: a robot with trustworthy perception, honest localization and an accurate, current map, planning and replanning a safe path through real, moving obstacles fast enough to matter.', 'boss', ARRAY['lin','imani','sera','byte'], '{"requiredMissionIds":["mission-vec-path-planning-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"evacuate-the-sector-boss-sim"}'::jsonb, '{"xp":1800,"credits":360,"badgeIds":["evacuate-the-sector"],"skillXp":{"robotics_fundamentals":250}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-path-planning-01', 1, 'imani', 'Full evacuation drill, sector 7, in six hours. Every person out, no confusion, no delay -- and this time a robot walks the corridor alongside them instead of watching from a fixed camera.'),
  ('mission-vec-path-planning-01', 2, 'imani', 'Perceive, localize, map -- Vector Division has all three working. What has never been tested together is the fourth piece: whether the robot can actually plan a route through what it now knows, live, with people moving through it.'),
  ('mission-vec-path-planning-01', 3, 'lin', 'A plan needs a shape to reason about. Not a photograph of the sector -- a graph. Every place the robot could stand becomes a node. Every way to get from one place to another becomes an edge. Distance, difficulty, risk -- all of that becomes a weight on the edge.'),
  ('mission-vec-path-planning-01', 4, 'lin', 'Reduce the sector to that shape and pathfinding stops being a robotics problem. It becomes a graph problem, and graph problems have decades of solved algorithms behind them.'),
  ('mission-vec-path-planning-01', 5, 'byte', 'I already have Act 23''s current SLAM map. Turning it into a graph the planner can search is the first real step toward a route this robot can actually follow today.'),

  ('mission-vec-path-planning-02', 1, 'lin', 'The simplest way to build that graph automatically is a grid. Lay a regular grid of cells over the sector''s occupancy map. Every free cell becomes a node. Every pair of neighboring free cells becomes an edge.'),
  ('mission-vec-path-planning-02', 2, 'byte', 'Sector 7''s grid comes out to roughly forty thousand cells at ten-centimeter resolution. That is not a hand-drawn graph anymore -- it is something only a computer could search in time for a drill.'),
  ('mission-vec-path-planning-02', 3, 'lin', 'Which raises the real question: how many neighbors does each cell actually connect to? Four, sharing an edge -- or eight, including diagonals?'),

  ('mission-vec-path-planning-03', 1, 'lin', 'Before weights enter the picture, recall the two plain graph searches. Breadth-first search explores everything one edge away, then everything two edges away, expanding outward in layers.'),
  ('mission-vec-path-planning-03', 2, 'lin', 'Depth-first search does the opposite -- it commits to one path as deep as it can go before ever backing up to try another branch.'),
  ('mission-vec-path-planning-03', 3, 'lin', 'On a graph where every edge counts as the same cost, BFS is guaranteed to find the path with the fewest edges. DFS makes no such promise -- it might stumble onto a long, winding route long before it ever finds a short one.'),

  ('mission-vec-path-planning-04', 1, 'lin', 'Once every edge has a real weight -- distance, difficulty, risk -- fewest edges stops being the right question. Dijkstra''s algorithm answers the right one: lowest total cost, guaranteed, as long as no edge weight is negative.'),
  ('mission-vec-path-planning-04', 2, 'lin', 'It always expands the cheapest reachable node next, and once a node is finalized, it is provably the lowest-cost way to reach it. No shortcut discovered later can ever beat it.'),
  ('mission-vec-path-planning-04', 3, 'byte', 'Running it on the sector graph, the cheapest route to the muster point is not the geometrically shortest one. It runs through a wider corridor instead of the narrow service passage, because the passage''s weight accounts for how long single-file movement takes to clear it.'),

  ('mission-vec-path-planning-05', 1, 'lin', 'Dijkstra is correct, but it wastes effort -- it explores every direction equally, with no sense of which way the goal actually is. A* fixes that with one addition: a heuristic, an estimate of remaining distance to the goal, added to the cost so far.'),
  ('mission-vec-path-planning-05', 2, 'lin', 'At every step A* prioritizes the node whose cost-so-far plus estimated-cost-to-goal looks smallest. It searches in the goal''s general direction instead of spreading out evenly in every direction.'),
  ('mission-vec-path-planning-05', 3, 'lin', 'It keeps Dijkstra''s optimality guarantee too, on one condition: the heuristic can never overestimate the true remaining distance. Break that condition and the guarantee breaks with it.'),

  ('mission-vec-path-planning-06', 1, 'lin', 'A heuristic is just a fast estimate, computed without actually searching the graph. On a grid, straight-line distance to the goal is a common choice -- cheap to compute, and it can never be longer than the true shortest path over open ground.'),
  ('mission-vec-path-planning-06', 2, 'lin', 'On a grid where diagonal moves are not allowed, Manhattan distance -- the sum of horizontal and vertical distance -- fits even better, because it never overestimates what the grid actually allows.'),
  ('mission-vec-path-planning-06', 3, 'byte', 'Pick a heuristic that overestimates, even occasionally, and A* can return a route that looks optimal and is not. It will still be a valid route to the goal. It will not necessarily be the cheapest one.'),

  ('mission-vec-path-planning-07', 1, 'lin', 'A graph edge needs a weight before Dijkstra or A* can use it. In the real sector, that weight comes from a cost map -- Act 23''s current SLAM map, with a number assigned to every cell for how expensive it actually is to move through.'),
  ('mission-vec-path-planning-07', 2, 'sera', 'Cost is not just distance. A cell one meter from a wall carries almost no margin if a sensor reads slightly off or a person steps sideways. I want every cell near an obstacle inflated -- costed higher -- long before the robot ever gets close enough for that margin to matter.'),
  ('mission-vec-path-planning-07', 3, 'lin', 'That inflation is deliberate, not noise. A path that hugs a wall might be geometrically shorter. A cost map makes the planner prefer the route with margin, without ever having to hard-code a single rule about walls.'),

  ('mission-vec-path-planning-08', 1, 'lin', 'Put a cost map and A* together and you get global planning -- one full search across the entire known sector, from the robot''s start to the muster point, before the robot ever takes a step.'),
  ('mission-vec-path-planning-08', 2, 'imani', 'Global planning only works if the map underneath it is real. Give it Act 23''s current SLAM map and it plans against the sector as it actually is right now. Give it an old floor plan and it confidently plans a route through a corridor that no longer exists that way.'),
  ('mission-vec-path-planning-08', 3, 'lin', 'That is the whole point of everything since Act 21. Perception feeds localization, localization feeds mapping, and mapping is what a global plan is actually allowed to trust.'),

  ('mission-vec-path-planning-09', 1, 'lin', 'A global plan is a route, not a moment-to-moment set of instructions. Local planning takes over inside a short horizon around the robot right now, replanning many times a second against whatever is actually being seen live.'),
  ('mission-vec-path-planning-09', 2, 'byte', 'The global route says which corridor to take. Local planning is what decides, this instant, how close to hug the left wall versus the right one, based on what is actually in view -- not what the global map assumed.'),
  ('mission-vec-path-planning-09', 3, 'lin', 'It stays close to the global path by design. It just never trusts the global path blindly, because the global map is already seconds old by the time the robot gets there.'),

  ('mission-vec-path-planning-10', 1, 'lin', 'Local planning earns its keep the moment something appears that the global cost map never accounted for. Obstacle avoidance is the specific job of adjusting the robot''s immediate path or speed to keep clear of it.'),
  ('mission-vec-path-planning-10', 2, 'sera', 'Clear of it, with margin, not just clear of collision. A route that technically misses an obstacle by two centimeters is not a safe route in a corridor full of moving people. I want distance, not a near miss treated as a success.'),
  ('mission-vec-path-planning-10', 3, 'lin', 'Which means avoidance is not one reflex. Slow down and hold course if the gap is workable. Steer around if there is room. Stop entirely if there is not -- and only ever resume once the gap is real again.'),

  ('mission-vec-path-planning-11', 1, 'lin', 'Everything so far treated obstacles as if they hold still once detected. An evacuation drill guarantees they will not. A dynamic obstacle is one whose position changes on its own, independent of anything the robot does.'),
  ('mission-vec-path-planning-11', 2, 'imani', 'Which means one sensor reading is a single frame, not the whole obstacle. Reacting to where a person is standing right now guarantees the robot is always responding to where they already were.'),
  ('mission-vec-path-planning-11', 3, 'lin', 'Static obstacle avoidance needed one clean read. A dynamic obstacle needs the planner to keep reading, keep predicting where that motion is headed, and keep replanning -- continuously, for as long as the obstacle stays near the path.'),

  ('mission-vec-path-planning-12', 1, 'imani', 'Sector 7, live drill, real people moving toward the muster point. Perceive, localize, map, plan -- every piece Vector Division has built since Act 18, running together, right now.'),
  ('mission-vec-path-planning-12', 2, 'sera', 'My requirement has not changed all Act: not just a path that reaches the goal, but a path that keeps real margin from every obstacle, static or moving, the entire way there.'),
  ('mission-vec-path-planning-12', 3, 'lin', 'Plan the global route first -- A* over the current cost map, not an assumed one. Then hold local planning ready to answer for anything that route could never have known about in advance.'),
  ('mission-vec-path-planning-12', 4, 'byte', 'Two evacuees just crossed the planned corridor mid-route, not on any cost map because they were not there when it was built. The global plan alone would walk the robot straight through where they are standing right now.'),
  ('mission-vec-path-planning-12', 5, 'lin', 'That is exactly the moment the whole stack either holds together or does not. Global route from a real map, local replanning from what is actually being sensed, and every input confirmed real before any of it is trusted.'),
  ('mission-vec-path-planning-12', 6, 'sera', 'It held. Full margin the entire route, live obstacles included, muster point reached inside the drill window. That is what a robot actually getting somewhere safely looks like, not just on paper.'),
  ('mission-vec-path-planning-12', 7, 'imani', 'That closes Arc IV. You went in able to say a robot knows where it is. You come out with one that can plan and replan a safe path through real, moving obstacles, fast enough to matter -- and every piece of it still exists as one-off code bolted onto a single robot. Scaling that to a whole fleet needs a real shared framework, not another custom build per machine. Next: ROS 2.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-path-planning-01-o1', 'mission-vec-path-planning-01', 1, 'Define the graph model', 'Choose the accurate description of how the sector becomes a graph a planner can search.'),
  ('mission-vec-path-planning-01-o2', 'mission-vec-path-planning-01', 2, 'Map the sector to a graph', 'Sort sector features into the graph role they actually play.'),

  ('mission-vec-path-planning-02-o1', 'mission-vec-path-planning-02', 1, 'Explain grid decomposition', 'Choose the accurate description of how a grid turns a map into a searchable graph.'),
  ('mission-vec-path-planning-02-o2', 'mission-vec-path-planning-02', 2, 'Judge the connectivity choice', 'Decide the real tradeoff between 4-connected and 8-connected grids for this corridor.'),

  ('mission-vec-path-planning-03-o1', 'mission-vec-path-planning-03', 1, 'Tell BFS from DFS', 'Choose the accurate distinction between how breadth-first and depth-first search explore a graph.'),
  ('mission-vec-path-planning-03-o2', 'mission-vec-path-planning-03', 2, 'Judge what the fewest-edges guarantee misses', 'State why BFS''s fewest-edge path is not automatically the best evacuation route.'),

  ('mission-vec-path-planning-04-o1', 'mission-vec-path-planning-04', 1, 'Define the shortest-path guarantee', 'Choose the accurate description of what Dijkstra''s algorithm actually guarantees.'),
  ('mission-vec-path-planning-04-o2', 'mission-vec-path-planning-04', 2, 'Judge the cheapest route', 'Given the sector''s weighted routes, judge which one Dijkstra would actually select.'),

  ('mission-vec-path-planning-05-o1', 'mission-vec-path-planning-05', 1, 'Define what A* adds', 'Choose the accurate description of what A* adds to Dijkstra''s search.'),
  ('mission-vec-path-planning-05-o2', 'mission-vec-path-planning-05', 2, 'Judge the optimality condition', 'State the one condition a heuristic must satisfy for A* to still guarantee the lowest-cost path.'),

  ('mission-vec-path-planning-06-o1', 'mission-vec-path-planning-06', 1, 'Choose a valid heuristic', 'Sort each candidate heuristic into admissible (never overestimates) or inadmissible for the sector''s grid.'),
  ('mission-vec-path-planning-06-o2', 'mission-vec-path-planning-06', 2, 'Judge the risk of overestimating', 'State what actually goes wrong when A* runs with a heuristic that can overestimate.'),

  ('mission-vec-path-planning-07-o1', 'mission-vec-path-planning-07', 1, 'Define a cost map', 'Choose the accurate description of what a cost map actually represents.'),
  ('mission-vec-path-planning-07-o2', 'mission-vec-path-planning-07', 2, 'Explain the inflation requirement', 'Find the evidence explaining why cells near obstacles are deliberately costed higher than the open floor around them.'),

  ('mission-vec-path-planning-08-o1', 'mission-vec-path-planning-08', 1, 'Define global planning', 'Choose the accurate description of what a global plan actually is and when it is computed.'),
  ('mission-vec-path-planning-08-o2', 'mission-vec-path-planning-08', 2, 'Judge which map it must run on', 'Find the evidence proving the global planner must run on the live, current SLAM map rather than an old floor plan.'),

  ('mission-vec-path-planning-09-o1', 'mission-vec-path-planning-09', 1, 'Define local planning', 'Choose the accurate description of what local planning actually does, and how often.'),
  ('mission-vec-path-planning-09-o2', 'mission-vec-path-planning-09', 2, 'Judge why global planning alone is not enough', 'State why the robot still needs a local planner even with a correct, current global route.'),

  ('mission-vec-path-planning-10-o1', 'mission-vec-path-planning-10', 1, 'Define obstacle avoidance', 'Choose the accurate description of what obstacle avoidance actually adjusts, and based on what.'),
  ('mission-vec-path-planning-10-o2', 'mission-vec-path-planning-10', 2, 'Judge the correct avoidance response', 'Given a live obstacle in the corridor, judge which reading actually requires the robot to slow or stop.'),

  ('mission-vec-path-planning-11-o1', 'mission-vec-path-planning-11', 1, 'Tell static from dynamic obstacles', 'Sort each obstacle into static (fixed) or dynamic (moving on its own).'),
  ('mission-vec-path-planning-11-o2', 'mission-vec-path-planning-11', 2, 'Judge what a dynamic obstacle requires', 'State what a dynamic obstacle actually requires from the planner that a static one does not.'),

  ('mission-vec-path-planning-12-o1', 'mission-vec-path-planning-12', 1, 'Plan the global route', 'Using A* and the current cost map, judge which global route to the muster point Vector Division should commit to before the drill starts moving.'),
  ('mission-vec-path-planning-12-o2', 'mission-vec-path-planning-12', 2, 'Replan around the dynamic obstacle', 'Given evacuees now crossing the planned corridor mid-route, judge the correct local-planning response.'),
  ('mission-vec-path-planning-12-o3', 'mission-vec-path-planning-12', 3, 'Confirm the real stack', 'Find the evidence proving the plan runs on real live perception, real localization and a real current map, not idealized assumptions.'),
  ('mission-vec-path-planning-12-o4', 'mission-vec-path-planning-12', 4, 'State the diagnosis', 'Having judged the global route, the local replan and the stack behind them, state what actually let Vector Division evacuate the sector safely.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-path-planning-01-o1-c1', 'mission-vec-path-planning-01-o1', 1, 'multiple_choice', 'In the graph Lin wants built from the sector''s map, what do nodes, edges and weights each represent?', '{"question":"In the graph Lin wants built from the sector''s map, what do nodes, edges and weights each represent?","options":[{"id":"a","text":"Nodes are obstacles, edges are walls, weights are colors on the map"},{"id":"b","text":"Nodes are places the robot could stand, edges are ways to move between two of them, and weights are the cost -- distance, difficulty or risk -- of using that edge"},{"id":"c","text":"Nodes and edges are the same thing, weights are unused"},{"id":"d","text":"Nodes are only the start and the goal, nothing else"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-01-o2-c1', 'mission-vec-path-planning-01-o2', 1, 'drag_and_drop', 'Sort each sector feature into the graph role it actually plays.', '{"items":[{"id":"i1","text":"A waypoint in the middle of an open corridor junction"},{"id":"i2","text":"The corridor segment connecting two junctions, forty meters long"},{"id":"i3","text":"A doorway currently propped open, connecting two corridors"},{"id":"i4","text":"The extra time cost of moving through a narrow doorway versus an open corridor"}],"targets":[{"id":"node","label":"Node"},{"id":"edge","label":"Edge"},{"id":"weight","label":"Weight"}]}'::jsonb, '{"correctMapping":{"i1":"node","i2":"edge","i3":"edge","i4":"weight"}}'::jsonb),

  ('mission-vec-path-planning-02-o1-c1', 'mission-vec-path-planning-02-o1', 1, 'multiple_choice', 'Overlaying a sector''s map with a grid and connecting neighboring free cells produces...', '{"question":"Overlaying a sector''s map with a grid and connecting neighboring free cells produces...","options":[{"id":"a","text":"A single node representing the whole sector"},{"id":"b","text":"A graph where each free cell is a node and each pair of adjacent free cells is an edge, ready for the same search algorithms that work on any graph"},{"id":"c","text":"A list of obstacles with no connectivity at all"},{"id":"d","text":"A graph that only a human can search"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-02-o2-c1', 'mission-vec-path-planning-02-o2', 1, 'multiple_choice', 'An 8-connected grid allows diagonal moves between cells; a 4-connected grid does not. What is the real tradeoff?', '{"question":"An 8-connected grid allows diagonal moves between cells; a 4-connected grid does not. What is the real tradeoff?","options":[{"id":"a","text":"There is no tradeoff, 8-connected is strictly better"},{"id":"b","text":"8-connected paths can look shorter and more natural, but diagonal moves can cut dangerously close to a corner obstacle that a 4-connected path would have gone around"},{"id":"c","text":"4-connected grids cannot represent corridors at all"},{"id":"d","text":"Diagonal moves are always cheaper than straight moves"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-path-planning-03-o1-c1', 'mission-vec-path-planning-03-o1', 1, 'multiple_choice', 'The real difference between BFS and DFS is...', '{"question":"The real difference between BFS and DFS is...","options":[{"id":"a","text":"BFS explores outward in layers, guaranteeing the fewest-edge path in an unweighted graph; DFS commits to one path as deep as possible before backtracking, with no such guarantee"},{"id":"b","text":"They always visit nodes in exactly the same order"},{"id":"c","text":"DFS is simply a faster version of BFS"},{"id":"d","text":"BFS only works on trees, not general graphs"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-path-planning-03-o2-c1', 'mission-vec-path-planning-03-o2', 1, 'multiple_choice', 'BFS guarantees the fewest-edge path through the sector''s corridor graph. Why is that not automatically the best evacuation route?', '{"question":"BFS guarantees the fewest-edge path through the sector''s corridor graph. Why is that not automatically the best evacuation route?","options":[{"id":"a","text":"Fewest edges is always identical to shortest real-world distance and lowest risk, so it is already the best route"},{"id":"b","text":"Fewest edges only counts hops, not the real cost of each edge -- a route with fewer, longer or more dangerous edges can be worse than a route with more, shorter, safer ones"},{"id":"c","text":"BFS cannot run on a grid graph at all"},{"id":"d","text":"Fewest edges guarantees the fastest route regardless of corridor width or crowding"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-path-planning-04-o1-c1', 'mission-vec-path-planning-04-o1', 1, 'multiple_choice', 'Dijkstra''s algorithm, run on a graph with non-negative edge weights, guarantees...', '{"question":"Dijkstra''s algorithm, run on a graph with non-negative edge weights, guarantees...","options":[{"id":"a","text":"The path with the fewest total edges, ignoring weight"},{"id":"b","text":"The path with the lowest total weight from the start node to every other node it reaches, by always expanding the cheapest known frontier node next"},{"id":"c","text":"A random valid path with no optimality guarantee"},{"id":"d","text":"The path that visits the most nodes"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-04-o2-c1', 'mission-vec-path-planning-04-o2', 1, 'investigation', 'Which route would Dijkstra actually select as lowest total cost?', '{"evidence":[{"id":"e1","label":"Route A","detail":"Geometrically shortest at 38 meters, but crosses a narrow service passage weighted at high cost due to single-file crowd movement"},{"id":"e2","label":"Route B","detail":"62 meters, runs through a wide corridor weighted at low cost per meter under crowd conditions, total weighted cost lower than Route A"},{"id":"e3","label":"Route C","detail":"A route through a currently sealed maintenance door, not traversable at all"}],"question":"Which route would Dijkstra actually select as lowest total cost?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-path-planning-05-o1-c1', 'mission-vec-path-planning-05-o1', 1, 'multiple_choice', 'A* improves on Dijkstra by...', '{"question":"A* improves on Dijkstra by...","options":[{"id":"a","text":"Ignoring edge weights entirely"},{"id":"b","text":"Adding a heuristic estimate of remaining distance to the goal, so the search is guided toward the goal instead of expanding equally in every direction"},{"id":"c","text":"Searching depth-first instead of by cost"},{"id":"d","text":"Removing the need for a graph altogether"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-05-o2-c1', 'mission-vec-path-planning-05-o2', 1, 'multiple_choice', 'For A* to still guarantee the lowest-cost path, its heuristic must...', '{"question":"For A* to still guarantee the lowest-cost path, its heuristic must...","options":[{"id":"a","text":"Always overestimate the true remaining cost, to search faster"},{"id":"b","text":"Never overestimate the true remaining cost to the goal -- it may underestimate, but never claim less distance remains than actually does"},{"id":"c","text":"Be updated by the robot''s actuators in real time"},{"id":"d","text":"Always equal exactly the true remaining cost, or the search fails"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-path-planning-06-o1-c1', 'mission-vec-path-planning-06-o1', 1, 'drag_and_drop', 'Sort each candidate heuristic into admissible (never overestimates) or inadmissible.', '{"items":[{"id":"h1","text":"Straight-line (Euclidean) distance to the goal, on a grid where diagonal movement is allowed"},{"id":"h2","text":"Manhattan distance to the goal, on a grid where only horizontal and vertical movement is allowed"},{"id":"h3","text":"Straight-line distance to the goal, multiplied by three, to make the search move faster"},{"id":"h4","text":"A fixed large constant added to straight-line distance, to encourage the search to finish sooner"}],"targets":[{"id":"admissible","label":"Admissible"},{"id":"inadmissible","label":"Inadmissible"}]}'::jsonb, '{"correctMapping":{"h1":"admissible","h2":"admissible","h3":"inadmissible","h4":"inadmissible"}}'::jsonb),
  ('mission-vec-path-planning-06-o2-c1', 'mission-vec-path-planning-06-o2', 1, 'multiple_choice', 'What actually goes wrong when A* runs with a heuristic that can overestimate the true remaining cost?', '{"question":"What actually goes wrong when A* runs with a heuristic that can overestimate the true remaining cost?","options":[{"id":"a","text":"Nothing, A* is always correct regardless of the heuristic"},{"id":"b","text":"A* can settle on a node too early, before a cheaper path to it is found, and return a valid but non-optimal route with no way to detect that it did"},{"id":"c","text":"The search simply refuses to run at all"},{"id":"d","text":"It only affects how the route looks visually, never its actual cost"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-path-planning-07-o1-c1', 'mission-vec-path-planning-07-o1', 1, 'multiple_choice', 'A cost map, built on top of Act 23''s current SLAM map, is best described as...', '{"question":"A cost map, built on top of Act 23''s current SLAM map, is best described as...","options":[{"id":"a","text":"A copy of the occupancy map with no new information"},{"id":"b","text":"A layer that assigns every traversable cell a numeric cost -- reflecting distance, difficulty or safety margin -- for the planner to weight its search with"},{"id":"c","text":"A list of every obstacle''s exact coordinates only"},{"id":"d","text":"A record of where the robot has already been"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-07-o2-c1', 'mission-vec-path-planning-07-o2', 1, 'investigation', 'Why are cells near obstacles deliberately costed higher than the open floor around them?', '{"evidence":[{"id":"e1","label":"Sera''s safety note","detail":"Cells within a set clearance distance of any mapped obstacle are inflated to a higher cost, so the planner prefers routes with margin before the robot is ever physically close enough for a sensor or localization error to matter"},{"id":"e2","label":"Facilities note","detail":"The sector''s corridors were last repainted two years ago"},{"id":"e3","label":"Byte''s log","detail":"The SLAM map used to build the cost map was refreshed at the start of the drill"}],"question":"Why are cells near obstacles deliberately costed higher than the open floor around them?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-path-planning-08-o1-c1', 'mission-vec-path-planning-08-o1', 1, 'multiple_choice', 'Global planning is best described as...', '{"question":"Global planning is best described as...","options":[{"id":"a","text":"A short, constantly repeated search covering only the next few meters"},{"id":"b","text":"One full search, using A* over the entire known cost map, producing a start-to-goal route before the robot moves"},{"id":"c","text":"A route drawn by hand ahead of the drill"},{"id":"d","text":"A search that ignores the cost map entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-08-o2-c1', 'mission-vec-path-planning-08-o2', 1, 'investigation', 'Which evidence proves the global planner must run on the live, current SLAM map rather than the old floor plan?', '{"evidence":[{"id":"e1","label":"Facilities archive","detail":"The original floor plan from construction shows a corridor that was permanently walled off during a later renovation"},{"id":"e2","label":"Byte''s log","detail":"The global planner is configured to read the cost map generated from Act 23''s live SLAM output, refreshed at the start of the drill"},{"id":"e3","label":"Old maintenance record","detail":"A previous audit found the archived floor plan disagreed with the corridor''s real layout in at least one place"}],"question":"Which evidence proves the global planner must run on the live, current SLAM map rather than the old floor plan?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-path-planning-09-o1-c1', 'mission-vec-path-planning-09-o1', 1, 'multiple_choice', 'Local planning is best described as...', '{"question":"Local planning is best described as...","options":[{"id":"a","text":"Recomputing the entire sector-wide global route from scratch every time"},{"id":"b","text":"A short-horizon plan around the robot''s current position, recomputed frequently, that follows the global route while reacting to what is actually being sensed live"},{"id":"c","text":"A plan that ignores the global route entirely"},{"id":"d","text":"A one-time plan computed before the robot starts moving, never updated"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-09-o2-c1', 'mission-vec-path-planning-09-o2', 1, 'multiple_choice', 'The global route is correct and current. Why does the robot still need a local planner?', '{"question":"The global route is correct and current. Why does the robot still need a local planner?","options":[{"id":"a","text":"It does not, a correct global route is always enough on its own"},{"id":"b","text":"The global map cannot capture everything that changes between refreshes -- a cart rolled into the corridor, a door propped differently -- and the robot needs to react to what it senses right now, not what the map assumed"},{"id":"c","text":"Local planning exists only to make the robot move more slowly"},{"id":"d","text":"The global planner cannot compute a route through corridors at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-path-planning-10-o1-c1', 'mission-vec-path-planning-10-o1', 1, 'multiple_choice', 'Obstacle avoidance, inside local planning, is best described as...', '{"question":"Obstacle avoidance, inside local planning, is best described as...","options":[{"id":"a","text":"Recomputing the global route from the start node every time"},{"id":"b","text":"Adjusting the robot''s immediate heading and speed, based on what is actually being sensed live, to maintain safe clearance from something the map did not account for"},{"id":"c","text":"A fixed rule to always stop the instant anything is detected"},{"id":"d","text":"A setting that only matters after a collision has already happened"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-10-o2-c1', 'mission-vec-path-planning-10-o2', 1, 'investigation', 'Given the two live readings and Sera''s minimum clearance standard, which situation requires the robot to actively slow or stop rather than simply hold course?', '{"evidence":[{"id":"e1","label":"Sensor reading","detail":"A person crossing the corridor twelve meters ahead, current gap to the nearest safe path edge is thirty centimeters and closing"},{"id":"e2","label":"Sensor reading","detail":"A cart parked against the far wall, current gap to the nearest safe path edge is one and a half meters and stable"},{"id":"e3","label":"Sera''s standard","detail":"Minimum acceptable clearance in a crowded corridor during the drill is set at one meter"}],"question":"Which situation requires the robot to actively slow or stop rather than simply hold course?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-path-planning-11-o1-c1', 'mission-vec-path-planning-11-o1', 1, 'drag_and_drop', 'Sort each obstacle into static or dynamic.', '{"items":[{"id":"b1","text":"A fixed shelving unit bolted to the corridor wall"},{"id":"b2","text":"A person walking toward the muster point at their own pace"},{"id":"b3","text":"A cart left parked and unattended against the far wall"},{"id":"b4","text":"A second evacuation robot moving through the same sector on its own route"}],"targets":[{"id":"static","label":"Static"},{"id":"dynamic","label":"Dynamic"}]}'::jsonb, '{"correctMapping":{"b1":"static","b2":"dynamic","b3":"static","b4":"dynamic"}}'::jsonb),
  ('mission-vec-path-planning-11-o2-c1', 'mission-vec-path-planning-11-o2', 1, 'multiple_choice', 'What does a dynamic obstacle actually require from the planner that a static one does not?', '{"question":"What does a dynamic obstacle actually require from the planner that a static one does not?","options":[{"id":"a","text":"Nothing extra, a single sensor reading is enough either way"},{"id":"b","text":"Continuous re-sensing and replanning, because a single position reading only describes where the obstacle was at that instant -- not where it is moving toward"},{"id":"c","text":"A permanently blocked route around the obstacle''s original position"},{"id":"d","text":"Ignoring the obstacle entirely, since it will move on its own"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-path-planning-12-o1-c1', 'mission-vec-path-planning-12-o1', 1, 'browser_simulation', 'Which candidate route should the global planner commit to before the drill starts moving?', '{"screen":"GLOBAL PLANNER -- CANDIDATE ROUTES, SECTOR 7","question":"Which candidate route should the global planner commit to before the drill starts moving?","records":[{"id":"r1","code":"ROUTE_A","detail":"41m via the main corridor, low average cost per meter, full clearance from all mapped obstacles"},{"id":"r2","code":"ROUTE_B","detail":"33m via the service passage, shorter distance but higher total weighted cost due to single-file crowd-clearance time and reduced obstacle margin"},{"id":"r3","code":"ROUTE_C","detail":"29m through a currently sealed maintenance door, not traversable"},{"id":"r4","code":"ROUTE_D","detail":"52m via the loading dock, valid but the highest total weighted cost of all traversable options"}]}'::jsonb, '{"correctOptionId":"r1"}'::jsonb),
  ('mission-vec-path-planning-12-o2-c1', 'mission-vec-path-planning-12-o2', 1, 'multiple_choice', 'Two evacuees are now crossing the planned corridor mid-route, not present on the cost map used to compute the global plan. What is the correct local-planning response?', '{"question":"Two evacuees are now crossing the planned corridor mid-route, not present on the cost map used to compute the global plan. What is the correct local-planning response?","options":[{"id":"a","text":"Continue following the global route exactly as planned, since the global plan was already computed correctly"},{"id":"b","text":"Use local planning to slow, hold or steer within the corridor''s safe margin around the evacuees'' live positions, replanning continuously until the path ahead is clear again, without abandoning the global route''s overall direction"},{"id":"c","text":"Immediately recompute an entirely new global route from scratch before moving at all"},{"id":"d","text":"Stop permanently and wait for the drill to be manually restarted"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-path-planning-12-o3-c1', 'mission-vec-path-planning-12-o3', 1, 'investigation', 'Which evidence proves today''s drill plan runs on the real perception, localization and mapping stack, not an idealized assumption?', '{"evidence":[{"id":"e1","label":"Byte''s stack audit","detail":"The global plan reads cost from Act 23''s live SLAM map, refreshed at drill start; robot pose comes from Act 22''s active localization filter, updated continuously; and local obstacle detection reads Act 21''s live perception pipeline, not a canned or idealized simulation feed"},{"id":"e2","label":"Old test log","detail":"An early bench test once ran the planner against a static, idealized map with no sensor noise modeled at all"},{"id":"e3","label":"Facilities note","detail":"Sector 7''s corridors were last repainted two years ago"}],"question":"Which evidence proves today''s drill plan runs on the real perception, localization and mapping stack, not an idealized assumption?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-path-planning-12-o4-c1', 'mission-vec-path-planning-12-o4', 1, 'boss_encounter', 'Having judged the global route, the local replan and the stack behind them, state what actually let Vector Division evacuate the sector safely.', '{"stages":[{"objectiveRef":"mission-vec-path-planning-12-o1","label":"Plan the global route"},{"objectiveRef":"mission-vec-path-planning-12-o2","label":"Replan around the dynamic obstacle"},{"objectiveRef":"mission-vec-path-planning-12-o3","label":"Confirm the real stack"}],"task":"State the diagnosis in one sentence: a robot with trustworthy perception, honest localization and an accurate, current map can plan and replan a safe path through real, moving obstacles fast enough to matter -- closing the gap between knowing where it is and actually getting somewhere safely."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-path-planning-12-o1","mission-vec-path-planning-12-o2","mission-vec-path-planning-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-path-planning-01-o1-c1', 'orientation', 'Ask what a node stands for, what an edge stands for, and what the number on an edge stands for, separately.', 10, 1),
  ('mission-vec-path-planning-01-o1-c1', 'concept', 'A graph only needs three ingredients: places, ways to move between them, and a cost for each way. Everything else about the sector is detail on top of that.', 20, 2),
  ('mission-vec-path-planning-01-o1-c1', 'solution', 'Nodes are places the robot could stand, edges are ways to move between two of them, and weights are the cost of using that edge.', 30, 3),
  ('mission-vec-path-planning-01-o2-c1', 'orientation', 'A junction is a place. A corridor segment is a way to move. A time cost is a number attached to a way to move.', 10, 1),
  ('mission-vec-path-planning-01-o2-c1', 'solution', 'Node: the junction. Edge: the corridor segment and the doorway. Weight: the extra time cost of the narrow doorway.', 20, 2),

  ('mission-vec-path-planning-02-o1-c1', 'orientation', 'Ask what each free grid cell becomes, and what connects two neighboring free cells.', 10, 1),
  ('mission-vec-path-planning-02-o1-c1', 'solution', 'Each free cell becomes a node, and each pair of adjacent free cells becomes an edge -- the same graph shape any search algorithm can already work with.', 20, 2),
  ('mission-vec-path-planning-02-o2-c1', 'orientation', 'Think about what happens to the safety margin around a corner obstacle when a move is allowed to cut diagonally past it.', 10, 1),
  ('mission-vec-path-planning-02-o2-c1', 'solution', '8-connected paths look shorter and more natural but can cut dangerously close to a corner obstacle that a 4-connected path would have gone around.', 20, 2),

  ('mission-vec-path-planning-03-o1-c1', 'orientation', 'One search expands outward evenly, layer by layer. The other commits to one direction until it has to back up.', 10, 1),
  ('mission-vec-path-planning-03-o1-c1', 'solution', 'BFS expands outward in layers, guaranteeing the fewest-edge path in an unweighted graph. DFS commits to depth first, with no such guarantee.', 20, 2),
  ('mission-vec-path-planning-03-o2-c1', 'orientation', 'Ask what BFS actually counts, and whether that count matches real distance or danger.', 10, 1),
  ('mission-vec-path-planning-03-o2-c1', 'solution', 'Fewest edges only counts hops, not real cost -- a route with fewer, longer or more dangerous edges can be worse than a route with more, shorter, safer ones.', 20, 2),

  ('mission-vec-path-planning-04-o1-c1', 'orientation', 'Ask what Dijkstra always expands next, and what that guarantees about a node once it is finalized.', 10, 1),
  ('mission-vec-path-planning-04-o1-c1', 'solution', 'Dijkstra guarantees the lowest total weight to every node it reaches, by always expanding the cheapest known frontier node next.', 20, 2),
  ('mission-vec-path-planning-04-o2-c1', 'orientation', 'Total weighted cost, not distance, is what Dijkstra actually minimizes.', 10, 1),
  ('mission-vec-path-planning-04-o2-c1', 'solution', 'e2, Route B, has the lower total weighted cost even though it is longer in distance -- that is what Dijkstra selects.', 20, 2),

  ('mission-vec-path-planning-05-o1-c1', 'orientation', 'Dijkstra already has the cost-so-far term. Ask what extra term A* adds on top of it.', 10, 1),
  ('mission-vec-path-planning-05-o1-c1', 'solution', 'A* adds a heuristic estimate of remaining distance to the goal, guiding the search toward the goal instead of spreading equally in every direction.', 20, 2),
  ('mission-vec-path-planning-05-o2-c1', 'orientation', 'Ask what would have to be true for the heuristic to never trick A* into settling too early.', 10, 1),
  ('mission-vec-path-planning-05-o2-c1', 'solution', 'The heuristic must never overestimate the true remaining cost -- it can underestimate, but never claim less distance remains than actually does.', 20, 2),

  ('mission-vec-path-planning-06-o1-c1', 'orientation', 'Ask whether each heuristic could ever claim less distance remains than the grid actually requires.', 10, 1),
  ('mission-vec-path-planning-06-o1-c1', 'solution', 'Admissible: straight-line distance with diagonals allowed, and Manhattan distance on a 4-connected grid. Inadmissible: straight-line distance multiplied by three, and a constant padded on top -- both can overestimate.', 20, 2),
  ('mission-vec-path-planning-06-o2-c1', 'orientation', 'Think about what happens if A* trusts a node is done before a cheaper path to it has actually been found.', 10, 1),
  ('mission-vec-path-planning-06-o2-c1', 'solution', 'A* can settle on a node too early and return a valid but non-optimal route, with no way to detect that it happened.', 20, 2),

  ('mission-vec-path-planning-07-o1-c1', 'orientation', 'A cost map is not just where obstacles are -- it is a number on every cell.', 10, 1),
  ('mission-vec-path-planning-07-o1-c1', 'solution', 'A cost map assigns every traversable cell a numeric cost -- distance, difficulty or safety margin -- for the planner to weight its search with.', 20, 2),
  ('mission-vec-path-planning-07-o2-c1', 'orientation', 'Look for the evidence that explains the reasoning behind the inflation, not just a fact about the corridor.', 10, 1),
  ('mission-vec-path-planning-07-o2-c1', 'solution', 'e1: cells near an obstacle are inflated so the planner prefers margin before the robot is ever physically close enough for sensor or localization error to matter.', 20, 2),

  ('mission-vec-path-planning-08-o1-c1', 'orientation', 'Ask when a global plan is computed relative to the robot actually moving, and how much of the map it covers.', 10, 1),
  ('mission-vec-path-planning-08-o1-c1', 'solution', 'Global planning is one full A* search over the entire known cost map, producing a start-to-goal route before the robot moves.', 20, 2),
  ('mission-vec-path-planning-08-o2-c1', 'orientation', 'Look for the evidence that describes what map the planner is actually configured to read from, not evidence about the old plan''s flaws.', 10, 1),
  ('mission-vec-path-planning-08-o2-c1', 'solution', 'e2: the global planner is configured to read the cost map generated from Act 23''s live SLAM output, refreshed at the start of the drill.', 20, 2),

  ('mission-vec-path-planning-09-o1-c1', 'orientation', 'Ask how much of the map local planning considers, and how often it is recomputed.', 10, 1),
  ('mission-vec-path-planning-09-o1-c1', 'solution', 'Local planning is a short-horizon plan around the robot''s current position, recomputed frequently, following the global route while reacting to live sensing.', 20, 2),
  ('mission-vec-path-planning-09-o2-c1', 'orientation', 'Think about how old the global map is by the time the robot physically reaches any given corridor.', 10, 1),
  ('mission-vec-path-planning-09-o2-c1', 'solution', 'The global map cannot capture everything that changes between refreshes, so the robot still needs to react to what it senses right now.', 20, 2),

  ('mission-vec-path-planning-10-o1-c1', 'orientation', 'Ask what obstacle avoidance actually changes about the robot''s motion, and what triggers that change.', 10, 1),
  ('mission-vec-path-planning-10-o1-c1', 'solution', 'It adjusts the robot''s immediate heading and speed, based on live sensing, to maintain safe clearance from something the map did not account for.', 20, 2),
  ('mission-vec-path-planning-10-o2-c1', 'orientation', 'Compare each gap against Sera''s one-meter minimum, not against zero.', 10, 1),
  ('mission-vec-path-planning-10-o2-c1', 'solution', 'e1: a thirty-centimeter gap that is closing is well under the one-meter minimum, and requires the robot to actively slow or stop.', 20, 2),

  ('mission-vec-path-planning-11-o1-c1', 'orientation', 'Ask whether each thing moves on its own, independent of the robot, or stays exactly where it was left.', 10, 1),
  ('mission-vec-path-planning-11-o1-c1', 'solution', 'Static: the bolted shelving unit and the parked cart. Dynamic: the walking person and the second robot, both moving on their own.', 20, 2),
  ('mission-vec-path-planning-11-o2-c1', 'orientation', 'Think about how quickly one sensor reading of a moving thing goes stale compared to one reading of a still thing.', 10, 1),
  ('mission-vec-path-planning-11-o2-c1', 'solution', 'A dynamic obstacle requires continuous re-sensing and replanning, since a single reading only describes where it was at that instant, not where it is heading.', 20, 2),

  ('mission-vec-path-planning-12-o1-c1', 'orientation', 'Rank the traversable routes by total weighted cost, not by raw distance, and drop the one that is not actually traversable.', 10, 1),
  ('mission-vec-path-planning-12-o1-c1', 'solution', 'r1, Route A, has the lowest total weighted cost with full clearance among the traversable options -- that is what the global planner should commit to.', 20, 2),
  ('mission-vec-path-planning-12-o2-c1', 'orientation', 'The correct response uses local planning to react to the evacuees without throwing away the global route''s direction entirely.', 10, 1),
  ('mission-vec-path-planning-12-o2-c1', 'solution', 'Slow, hold or steer within safe margin around the evacuees'' live positions, replanning continuously until clear, while keeping the global route''s overall direction.', 20, 2),
  ('mission-vec-path-planning-12-o3-c1', 'orientation', 'Look for the evidence that names all three real systems the plan actually reads from, not the old idealized bench test.', 10, 1),
  ('mission-vec-path-planning-12-o3-c1', 'solution', 'e1: Byte''s stack audit confirms the plan uses Act 23''s live map, Act 22''s active localization, and Act 21''s live perception -- not an idealized feed.', 20, 2),
  ('mission-vec-path-planning-12-o4-c1', 'orientation', 'Combine the real global route, the live local replan, and the confirmed real stack behind both into one statement about what actually made the drill safe.', 15, 1),
  ('mission-vec-path-planning-12-o4-c1', 'solution', 'A robot with trustworthy perception, honest localization and an accurate, current map can plan and replan a safe path through real, moving obstacles fast enough to matter -- closing the gap between knowing where it is and actually getting somewhere safely.', 25, 2);
